import sys

d = sys.stdin.read().split()
n, T = int(d[0]), int(d[1])
a = [int(x) for x in d[2:2 + n]]
cnt = 0
for mask in range(1 << n):
    s = 0
    for i in range(n):
        if mask >> i & 1:
            s += a[i]
    if s <= T:
        cnt += 1
print(cnt)

